    """宣言の JSON (dict) を検査し、パスをそろえ、種類を付ける。

    返り値: {"status": "ok", "declaration": {"files": [{"path", "units" (None なら全体), "kind" (filekinds.classify の結果)}],
    "resources": [...], "split": {"needed", "reason", "remaining", "blocked_by" (正規形の配列か None)}}, "count": ファイルの数, "errors": []}
