    if res["go"]:
        return (EXIT_CHANGED, "go")
    if res["returned"]:
        return (EXIT_CHANGED, "request")
    if (item.get("status") or {}).get("name") == "Blocked" and (st.get("declaration") or {}).get("manager_blocked"):
        return (EXIT_CHANGED, "wait")
    return None

